/* Chess against the head. Loaded by site.js on /hobbies/chess/.
   mount(el) builds the board inside el and returns a cleanup function.

   Rules come from chess.js (BSD-2-Clause, via esm.sh). The head's engine is
   below, a small alpha-beta that runs in a Web Worker made from a Blob.
   The board is physical: pieces lift when you pick them up, land with a little
   bounce and a clack, and captured pieces get knocked into the tray under the
   board, where they tumble around with simple 2D physics. Grab them and throw
   them. When it isn't your turn you can flick the pieces on the board too,
   they spring back. Reduced motion skips all of that.

   Stats load live from chess.com or lichess (/hobbies/chess/chess.json). */

import { Chess } from 'https://esm.sh/chess.js@1.4.0';

const CONFIG = '/hobbies/chess/chess.json';
const FACES = { neutral: '/media/head.webp', happy: '/media/head-happy.webp', sad: '/media/head-sad.webp' };
const DEPTH = 3;
const STATS_TTL = 10 * 60 * 1000;

// What the head says. A pool per moment; it won't say the same line twice in a row.
const LINES = {
  hello: ['your move. go easy on me', 'ok you start. no pressure', 'white suits you'],
  helloBlack: ['ok i go first', 'me first then. hmm', 'i\'ll start, don\'t judge the opening'],
  think: ['hmm', 'thinking', 'wait let me think', 'ok ok one sec'],
  good: ['wait that was a good move', 'oh. i didn\'t see that', 'ok that was clean'],
  free: ['wait is this free?', 'are you sure about that one', 'hmm i think you dropped something'],
  losing: ['ok i resign in my heart', 'this is going badly for me', 'i\'m just here for fun now'],
  winning: ['you can undo, i won\'t tell', 'i feel kinda bad now'],
  lostPiece: ['oh no not that one', 'ok i didn\'t need that', 'rip'],
  tookPiece: ['sorry', 'i\'ll give it back probably', 'oops'],
  checked: ['ah', 'ok ok i see it', 'check, huh'],
  check: ['check. sorry', 'check i think?'],
  promote: ['new queen huh', 'ok that pawn made it'],
  undo: ['sure, take it back', 'i didn\'t see anything', 'happens to me all the time'],
  youWin: ['ok you got me. gg', 'gg. you\'re actually good', 'gg, i\'ll be thinking about this one'],
  headWins: ['gg. that was close', 'gg, you had me for a while there', 'gg. rematch?'],
  draw: ['a draw. i\'ll take it', 'draw. fair'],
  stalemate: ['stalemate? i\'ll take that', 'stalemate. lucky me'],
  flick: ['hey', 'stop that', 'that tickles', 'my pieces!!', 'ok rude']
};

const CSS = `
.cx { --sq-l: #e8ebef; --sq-d: #b9c3cf; --acc: 136, 192, 208; --chk: 70, 146, 170; --dot: rgba(36, 48, 66, 0.2); --tray: rgba(0, 0, 0, 0.035); container-type: inline-size; user-select: none; -webkit-user-select: none; }
[data-theme="dark"] .cx { --sq-l: #5b6372; --sq-d: #424956; --chk: 136, 192, 208; --dot: rgba(10, 14, 20, 0.34); --tray: rgba(255, 255, 255, 0.04); }
.cx-wrap { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "head" "stage" "ctl" "moves" "stats"; }
.cx-head { grid-area: head; display: flex; align-items: center; gap: 12px; min-height: 64px; padding-bottom: 12px; }
.cx-face { position: relative; flex: none; width: 41px; height: 52px; }
.cx-face img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; transition: opacity 160ms ease; }
.cx-face img.off { opacity: 0; }
.cx-who { color: var(--t3); line-height: 1.35; }
.cx-say { color: var(--t1); line-height: 1.35; min-height: 1.35em; transition: opacity 160ms ease; }
.cx-say.swap { opacity: 0; }
.cx-say .dots::after { content: ''; animation: cx-dots 1.2s steps(4) infinite; }
@keyframes cx-dots { 0% { content: ''; } 25% { content: '.'; } 50% { content: '..'; } 75% { content: '...'; } }

.cx-stage { grid-area: stage; position: relative; }
.cx-board { position: relative; display: grid; grid-template: repeat(8, 1fr) / repeat(8, 1fr); aspect-ratio: 1; border-radius: 10px; overflow: hidden; -webkit-touch-callout: none; }
.cx-sq { position: relative; background: var(--sq-l); }
.cx-sq.d { background: var(--sq-d); }
.cx-sq.occ, .cx-tray { touch-action: none; }
.cx-sq::before, .cx-sq::after { content: ''; position: absolute; inset: 0; pointer-events: none; }
.cx-sq.last::before { background: rgba(var(--acc), 0.42); }
.cx-sq.sel::before { background: rgba(var(--acc), 0.66); }
.cx-sq.chk::before { background: radial-gradient(circle, rgba(var(--chk), 1) 0%, rgba(var(--chk), 0.75) 36%, rgba(var(--chk), 0) 74%); }
.cx-sq.to::after { background: radial-gradient(circle, var(--dot) 0 15%, transparent 16%); }
.cx-sq.to.cap::after { background: radial-gradient(circle, transparent 0 64%, var(--dot) 65% 76%, transparent 77%); }
.cx-sq.over::after { box-shadow: inset 0 0 0 3px rgba(var(--acc), 0.9); }
.cx-co { position: absolute; font-size: 10px; line-height: 1; font-weight: 500; color: var(--sq-d); pointer-events: none; }
.cx-sq.d .cx-co { color: var(--sq-l); }
.cx-co.r { top: 4px; left: 4px; }
.cx-co.f { right: 4px; bottom: 3px; }
.cx-tray { position: relative; margin-top: 1.5%; aspect-ratio: 16 / 3; border-radius: 10px; background: var(--tray); box-shadow: inset 0 0 0 1px var(--rule); }
.cx-tray-note { position: absolute; inset: 0; display: grid; place-items: center; color: var(--t3); pointer-events: none; transition: opacity 300ms ease; }
.cx-tray-note.off { opacity: 0; }
.cx-layer { position: absolute; inset: 0; pointer-events: none; }
.cx-pc { position: absolute; left: 0; top: 0; background-position: center; background-size: 100% 100%; background-repeat: no-repeat; will-change: transform; --lift: 0; filter: drop-shadow(0 calc(var(--lift) * 9px) calc(var(--lift) * 6px + 0.5px) rgba(0, 0, 0, calc(var(--lift) * 0.26))); }
.cx-pc.up { z-index: 10; }
.cx-pc.fly { z-index: 9; }
.cx-pc.out { opacity: 0; transition: opacity 200ms ease; }

.cx-promo { position: absolute; z-index: 20; inset: 0; border-radius: 10px; background: rgba(0, 0, 0, 0.18); }
.cx-promo-col { position: absolute; display: flex; flex-direction: column; width: 12.5%; border-radius: 10px; background: var(--bg); box-shadow: 0 0 0 1px var(--rule), 0 12px 32px -12px rgba(0, 0, 0, 0.4); overflow: hidden; }
.cx-promo-col.up { flex-direction: column-reverse; }
.cx-promo button { aspect-ratio: 1; padding: 6%; border: 0; background: none; cursor: pointer; }
.cx-promo button:hover { background: var(--fill); }
.cx-promo button i { display: block; width: 100%; height: 100%; background-position: center; background-size: 100% 100%; background-repeat: no-repeat; }

.cx-ctl { grid-area: ctl; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px; padding: 14px 0 12px; }
.cx-seg, .cx-acts { display: flex; align-items: center; gap: 2px; }
.cx-seg > span { margin-right: 8px; color: var(--t3); }
.cx button.cx-b { padding: 3px 10px; border: 0; border-radius: 8px; background: none; color: var(--t2); font: inherit; letter-spacing: inherit; cursor: pointer; transition: color 150ms ease, background 150ms ease; }
.cx button.cx-b:hover { color: var(--t1); }
.cx button.cx-b[aria-pressed="true"] { color: var(--t1); background: var(--fill); }
.cx button.cx-b:disabled { color: var(--t3); cursor: default; background: none; }
.cx-acts .cx-b:last-child { margin-right: -10px; }

.cx-moves { grid-area: moves; position: relative; border-top: 1px solid var(--rule); }
.cx-scroll { max-height: 9.6em; overflow-y: auto; padding: 10px 0; scrollbar-width: thin; }
.cx-list { display: grid; grid-template-columns: 2.4em minmax(0, 5.5em) minmax(0, 5.5em); gap: 1px 8px; color: var(--t2); line-height: 1.5; }
.cx-list .n { color: var(--t3); }
.cx-list .now { color: var(--t1); }
.cx-list .end { grid-column: 2 / -1; color: var(--t1); }
.cx-empty { color: var(--t3); }

.cx-stats { grid-area: stats; padding-top: 12px; border-top: 1px solid var(--rule); }
.cx-st-top { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; margin-bottom: 6px; }
.cx-st-top span { color: var(--t3); }
.cx-st-top a { color: var(--t2); }
.cx-st-top a:hover { color: var(--t1); }
.cx-grid { display: grid; grid-template-columns: minmax(4.4em, auto) minmax(3.2em, auto) minmax(3.2em, auto) minmax(0, 1fr); gap: 2px 14px; line-height: 1.6; }
.cx-grid .h { color: var(--t3); }
.cx-grid .k { color: var(--t2); }
.cx-grid .v { color: var(--t1); }
.cx-grid .w { color: var(--t2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cx-grid .m { color: var(--t3); }
.cx-soon { color: var(--t3); }

@container (min-width: 720px) {
  .cx-wrap { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); grid-template-rows: auto auto minmax(150px, 1fr) auto; grid-template-areas: "stage head" "stage ctl" "stage moves" "stage stats"; column-gap: 48px; }
  .cx-stage { align-self: start; }
  .cx-head { min-height: 0; padding: 0 0 12px; }
  .cx-scroll { position: absolute; inset: 0 0 12px; max-height: none; }
}
@media (prefers-reduced-motion: reduce) {
  .cx-say, .cx-face img, .cx-tray-note { transition: none; }
  .cx-say .dots::after { animation: none; content: '...'; }
}
`;

